function isAbortError(error: unknown): boolean {
  if (error instanceof Error) {
    if (error.name === "AbortError") return true;
    if (error.name === "DOMException" && (error as DOMException).code === 20) return true;
  }
  return false;
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      return;
    }

    let timer: ReturnType<typeof setTimeout> | undefined;
    let settled = false;

    const onAbort = () => {
      if (settled) return;
      settled = true;
      if (timer !== undefined) clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
      reject(signal?.reason ?? new DOMException("Aborted", "AbortError"));
    };

    timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

export async function retry<T>(
  operation: (signal: AbortSignal) => Promise<T>,
  options: {
    attempts: number;
    baseDelayMs: number;
    signal?: AbortSignal;
    shouldRetry?: (error: unknown) => boolean;
  }
): Promise<T> {
  const { attempts, baseDelayMs, signal, shouldRetry } = options;

  if (attempts < 1) {
    throw new RangeError("attempts must be at least 1");
  }

  let lastError: unknown;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException("Aborted", "AbortError");
    }

    try {
      return await operation(signal ?? new AbortController().signal);
    } catch (error) {
      lastError = error;

      if (isAbortError(error)) {
        throw error;
      }

      if (shouldRetry && !shouldRetry(error)) {
        throw error;
      }

      if (attempt === attempts) {
        break;
      }

      const delay = baseDelayMs * Math.pow(2, attempt - 1);

      try {
        await sleep(delay, signal);
      } catch (sleepError) {
        if (isAbortError(sleepError)) {
          throw sleepError;
        }
        throw sleepError;
      }
    }
  }

  throw lastError;
}
