export type ParsePaginationResult =
  | { ok: true; value: { page: number; pageSize: number; offset: number } }
  | { ok: false; error: string };

const ALLOWED_KEYS = new Set(['page', 'pageSize']);

function isSafeIntegerString(s: string): boolean {
  if (typeof s !== 'string') return false;
  if (s.length === 0) return false;
  // Reject leading/trailing whitespace
  if (s !== s.trim()) return false;
  // Reject signs (+, -)
  if (s[0] === '+' || s[0] === '-') return false;
  // Reject exponents
  if (s.includes('e') || s.includes('E')) return false;
  // Reject floats (decimal point)
  if (s.includes('.')) return false;
  // Must be all digits
  if (!/^\d+$/.test(s)) return false;
  // Reject leading zeros (e.g., "01") unless the string is exactly "0"
  if (s.length > 1 && s[0] === '0') return false;
  // Parse and check for unsafe integers (must be within safe integer range)
  const num = Number(s);
  if (!Number.isSafeInteger(num)) return false;
  return true;
}

export function parsePagination(
  query: Record<string, string | string[] | undefined>
): ParsePaginationResult {
  // Reject unknown keys
  for (const key of Object.keys(query)) {
    if (!ALLOWED_KEYS.has(key)) {
      return { ok: false, error: `Unknown key: ${key}` };
    }
  }

  // Reject arrays
  for (const key of Object.keys(query)) {
    const val = query[key];
    if (Array.isArray(val)) {
      return { ok: false, error: `Key "${key}" must not be an array` };
    }
  }

  // Process page
  let page: number;
  const pageRaw = query['page'];
  if (pageRaw === undefined) {
    page = 1;
  } else {
    if (typeof pageRaw !== 'string') {
      return { ok: false, error: 'page must be a string' };
    }
    if (!isSafeIntegerString(pageRaw)) {
      return { ok: false, error: 'page must be a safe positive integer string' };
    }
    page = Number(pageRaw);
    if (page < 1) {
      return { ok: false, error: 'page must be at least 1' };
    }
  }

  // Process pageSize
  let pageSize: number;
  const pageSizeRaw = query['pageSize'];
  if (pageSizeRaw === undefined) {
    pageSize = 20;
  } else {
    if (typeof pageSizeRaw !== 'string') {
      return { ok: false, error: 'pageSize must be a string' };
    }
    if (!isSafeIntegerString(pageSizeRaw)) {
      return { ok: false, error: 'pageSize must be a safe positive integer string' };
    }
    pageSize = Number(pageSizeRaw);
    if (pageSize < 1) {
      return { ok: false, error: 'pageSize must be at least 1' };
    }
    if (pageSize > 100) {
      return { ok: false, error: 'pageSize must not exceed 100' };
    }
  }

  const offset = (page - 1) * pageSize;

  return {
    ok: true,
    value: { page, pageSize, offset },
  };
}
